e class="table"><thead><tr><th>Сумма и срок</th><th>Способ</th><th>НДС</th><th>Комментарий</th></tr></thead><tbody><?php foreach($customerPayments as$payment):$method=(string)($payment['payment_method']??'cashless');$vat=$payment['vat_rate']===null?'':(string)$payment['vat_rate'];?><tr><td><?=e(WasteTripCustomerPaymentService::detail($payment))?></td><td><?=e(LinearRouteService::PAYMENT_METHODS[$method]??($method===''?'Не указан':$method))?></td><td><?=e(($payment['payment_type']??null)===''?'Не указан':(LinearRouteService::VAT_RATES[$vat]??($vat===''?'Без НДС':'НДС '.$vat.'%')))?></td><td><?=e((string)($payment['condition_comment']??'—'))?></td></tr><?php endforeach;?></tbody></table></div><?php endif; $carrierPayments=(array)($trip['carrier_payments']??[]);?><div class="section-title" style="margin-top:18px">Условия оплаты перевозчику</div><?php if($carrierPayments===[]):?><div class="notice warn">Ставка перевозчика не заполнена.</div><?php else:?><div style="margin:0 0 10px"><strong>Итого: <?=e(WasteTripCarrierPaymentService::total($carrierPayments))?></strong></div><div class="table-scroll"><table class="table"><thead><tr><th>Сумма и срок</th><th>Способ</th><th>НДС</th><th>Комментарий</th></tr></thead><tbody><?php foreach($carrierPayments as$payment):$method=(string)($payment['payment_method']??'cashless');$vat=$payment['vat_rate']===null?'':(string)$payment['vat_rate'];?><tr><td><?=e(WasteTripCarrierPaymentService::detail($payment))?></td><td><?=e(LinearRouteService::PAYMENT_METHODS[$method]??($method===''?'Не указан':$method))?></td><td><?=e(($payment['payment_type']??null)===''?'Не указан':(LinearRouteService::VAT_RATES[$vat]??($vat===''?'Без НДС':'НДС '.$vat.'%')))?></td><td><?=e((string)($payment['condition_comment']??'—'))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;endif;?><div class="section-title" style="margin-top:18px">Заявки ФЭО</div><div class="table-scroll"><table class="table"><thead><tr><th>#</th><th>Заявка</th><th>Грузоотправитель</th><th>Адрес</th><th>Отход</th><th>Snapshot, кг</th></tr></thead><tbody><?php foreach($trip['requests']??[] as$i=>$r):?><tr><td><?=$i+1?></td><td><?=e((string)$r['zayavka_id'])?></td><td><?=e((string)($r['naim_oo_gruzootpravitel']??'—'))?></td><td><?=e((string)($r['mno_adres_pogruzki']??'—'))?></td><td><?=e((string)($r['naim_otkhoda_fkko']??'—'))?></td><td><?=e($fmtKg($r['snapshot_mass_kg']??0))?></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal-foot is-spaced"><div><?php if(!in_array((string)$trip['status'],[WasteTripService::STATUS_COMPLETED,WasteTripService::STATUS_CANCELLED],true)):?><form method="post" action="<?=app_url('/company/trips/departures/'.$tripId.'/cancel')?>" style="display:flex;gap:8px" onsubmit="return confirm('Отменить рейс?');"><input type="hidden" name="lock_version" value="<?=(int)$trip['lock_version']?>"><input type="text" name="cancellation_reason" required maxlength="500" placeholder="Причина отмены"><button type="submit" class="btn btn-ghost">Отменить</button></form><?php endif;?></div><div class="modal-foot-actions"><button type="button" class="btn btn-ghost" onclick="closeModal('waste-trip-view-modal')">Закрыть</button><?php if((string)$trip['status']!==WasteTripService::STATUS_CANCELLED):?><button type="button" class="btn btn-primary" data-waste-open-edit="<?=$tripId?>">Редактировать</button><?php endif;?></div></div>
